//! Actions-only real Router/TLS/Common status consumption and original Join.
//! Incoming IM installation is explicit; status receipt is never message media
//! or a grant to issue refresh/setRead or user mark-read writes.
use super::*;
fn status_args(time:i64,key:&[u8],value:&[u8])->Vec<u8>{
    let time=time.to_string();let mut body=Writer::new();body.properties(&[RpcProperty{key,value}]).unwrap();let body=body.finish();let mut w=Writer::versioned().unwrap();w.bytes(n::im_status::STATUS_KIND).unwrap();w.properties(&[RpcProperty{key:b"Group.GroupId",value:b"1_2"},RpcProperty{key:b"Group.UpdateTime",value:time.as_bytes()}]).unwrap();w.bytes(body.expose_to_transport()).unwrap();w.finish().expose_to_transport().to_vec()
}
fn status(rpc:i32,time:i64,key:&[u8],value:&[u8])->Vec<u8>{direct(rpc,n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),&status_args(time,key,value),b"MessageReceiver",None)}
fn stored(db:&crate::platform::db::Database)->i64{db.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_status_observations",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap()}
fn property(db:&crate::platform::db::Database,key:&[u8])->(i64,Vec<u8>){db.with_conn(|c|c.query_row("SELECT update_time,status_value FROM app_voice_im_status_properties WHERE status_key=?1",[key],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|_|"fixture")).unwrap()}
async fn login_host(peer:&mut CommonPeer){let p=peer.next().await.unwrap();let login=decode_request(&p[1..]).unwrap();peer.send(&[reply(login.call_id,&login_result())]).await;let(_,flag)=hosting_call(peer).await;assert_eq!(flag,b"4");}
#[tokio::test]
async fn im_status_account_real_direct_commits_partial_properties_before_original_ack_without_any_read_query(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let cfg=config(&cert.root,port,3000);assert!(cfg.profile.im_sync.is_none());let account=manager.create(cfg,100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;
        peer.send(&[status(91,7,n::im_status::LAST_RECEIVED,b"9")]).await;next_reply(&mut peer,91,true).await;assert_eq!(property(&observed,n::im_status::LAST_RECEIVED),(7,b"9".to_vec()));
        peer.send(&[status(92,8,n::im_status::LAST_READ,b"7"),status(93,8,n::im_status::PEER_READ_NOTIFICATION,b"6")]).await;next_reply(&mut peer,92,true).await;next_reply(&mut peer,93,true).await;
        peer.send(&[status(94,7,n::im_status::LAST_READ,b"5"),status(95,8,n::im_status::LAST_READ,b"7")]).await;next_reply(&mut peer,94,true).await;next_reply(&mut peer,95,true).await;assert_eq!(stored(&observed),1);assert_eq!(count(&observed),0);assert_eq!(property(&observed,n::im_status::LAST_READ),(8,b"7".to_vec()));assert_eq!(property(&observed,n::im_status::PEER_READ_NOTIFICATION),(8,b"6".to_vec()));done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert!(manager.im_messages(&line,16).unwrap().is_empty());assert!(manager.messages(&line,16).unwrap().is_empty());assert!(temp.database.get_call_history_for_line(&line,16,0).unwrap().is_empty());assert!(temp.database.get_recent_app_events(Some(&line),16).unwrap().is_empty());let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert!(!view.incoming_call_ready&&!view.outbound_authorized);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert_eq!(stored(&temp.database),1);
    bounded(manager.delete(&line,account.revision)).await.unwrap();assert_eq!(stored(&temp.database),0);let properties:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_status_properties",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(properties,0);
}).await;}
async fn early(expired:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,if expired{100}else{3000}),100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;let p=peer.next().await.unwrap();let login=decode_request(&p[1..]).unwrap();peer.send(&[reply(login.call_id,&login_result()),status(91,7,n::im_status::LAST_RECEIVED,b"9")]).await;
        loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0,"no unconfirmed status receipt");let request=decode_request(&p[1..]).unwrap();assert_eq!(request.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(request.arguments).unwrap();r.bytes().unwrap();r.bytes().unwrap();let payload=n::rpc_batch::read_payload(&mut r).unwrap();let seq=payload.requests.keys().copied().next();if seq.is_some(){if expired{tokio::time::sleep(Duration::from_millis(150)).await;}assert_eq!(stored(&observed),0);assert_eq!(count(&observed),0);}peer.send(&[reply(request.call_id,&n::runtime_backend::tests::swap_result(seq,true,payload.fields))]).await;if seq.is_some(){break;}}
        next_reply(&mut peer,91,!expired).await;assert_eq!(stored(&observed),i64::from(!expired));done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert!(manager.im_messages(&line,16).unwrap().is_empty());assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}
#[tokio::test]async fn im_status_account_early_update_waits_for_same_hosting_ack_before_sql_and_reply(){Box::pin(early(false)).await;}
#[tokio::test]async fn im_status_account_early_expired_update_nacks_without_new_deadline_or_persistence(){Box::pin(early(true)).await;}
#[tokio::test]
async fn im_status_account_sql_failure_nacks_and_preserves_healthy_sdk_cleanup_without_status_or_messages(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,3000),100).await.unwrap().account;let line=account.line_id.clone();temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER reject_status BEFORE INSERT ON app_voice_im_status_properties BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;peer.send(&[status(91,7,n::im_status::LAST_READ,b"7")]).await;next_reply(&mut peer,91,false).await;done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert_eq!(stored(&temp.database),0);let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert_eq!(view.last_error,Some("app_account_im_storage_failed"));assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn im_status_account_read_observation_cannot_ack_message_hint_or_skip_current_message_storage(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,100),100).await.unwrap().account;let line=account.line_id.clone();let(done,finished)=tokio::sync::oneshot::channel();let observed=temp.database.clone();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;peer.send(&[status(91,7,n::im_status::LAST_READ,b"7")]).await;next_reply(&mut peer,91,true).await;peer.send(&[hint(92,99,7)]).await;next_reply(&mut peer,92,false).await;assert_eq!(count(&observed),0);peer.send(&[message(93,7,true)]).await;next_reply(&mut peer,93,true).await;assert_eq!(count(&observed),1);done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert_eq!(stored(&temp.database),1);assert_eq!(manager.im_messages(&line,16).unwrap().len(),1);assert!(manager.messages(&line,16).unwrap().is_empty());assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn im_status_account_authenticated_batch_holds_own_result_until_epoch_ack_then_original_direct_barrier_and_join(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,3000),100).await.unwrap().account;let line=account.line_id.clone();let observed=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;let p=peer.next().await.unwrap();let swap=decode_request(&p[1..]).unwrap();assert_eq!(swap.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(swap.arguments).unwrap();r.bytes().unwrap();r.bytes().unwrap();let payload=n::rpc_batch::read_payload(&mut r).unwrap();let mut w=Writer::new();w.boolean(true).unwrap();for v in [9,1,1,payload.fields[0],payload.fields[1],payload.fields[2]]{w.u32(v).unwrap();}w.u32(1).unwrap();w.i32(1).unwrap();w.bytes(n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes()).unwrap();w.bytes(&status_args(7,n::im_status::LAST_READ,b"7")).unwrap();w.properties(&[RpcProperty{key:b"id",value:b"MessageReceiver"}]).unwrap();w.u32(0).unwrap();w.properties(&[]).unwrap();w.bytes(b"").unwrap();peer.send(&[reply(swap.call_id,w.finish().expose_to_transport())]).await;
        loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0);let req=decode_request(&p[1..]).unwrap();assert_eq!(req.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes());let mut r=Reader::versioned(req.arguments).unwrap();r.bytes().unwrap();r.bytes().unwrap();let p=n::rpc_batch::read_payload(&mut r).unwrap();let done=p.results.contains_key(&1);if done{assert_eq!(p.results[&1].result_stream,[0,1,0,0,0,0]);assert_eq!(stored(&observed),1);assert_eq!(count(&observed),0);}peer.send(&[reply(req.call_id,&n::runtime_backend::tests::swap_result(None,true,p.fields))]).await;if done{break;}}
        peer.send(&[status(91,7,n::im_status::LAST_READ,b"7")]).await;next_reply(&mut peer,91,true).await;done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert_eq!(stored(&temp.database),1);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}).await;}
